begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('f2160000-0000-4000-8000-000000000001','run-a@mizyun.test'),('f2160000-0000-4000-8000-000000000002','run-b@mizyun.test');
create temporary table summary(value jsonb);
insert into summary values ('{"version":1,"activityDate":"2026-10-01","recordingTimezone":"Pacific/Kiritimati","timePrecision":"day","startedAt":null,"durationSeconds":1800,"durationBasis":"elapsed","distanceMeters":5000,"environment":"outdoor","perceivedExertion":null,"origin":{"kind":"manual"},"timestampEnvelope":"date_anchor","revision":1}');
create temporary table run_ids(id uuid);
grant select,update on summary to authenticated;grant all on run_ids to authenticated;
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='f2160000-0000-4000-8000-000000000001';
select ok(not has_function_privilege('anon','public.run_create(uuid,text,text,jsonb)','EXECUTE'),'Anon has no mutation grant');
select ok(not has_function_privilege('service_role','public.run_create(uuid,text,text,jsonb)','EXECUTE'),'Service role has no running mutation grant');
select throws_ok($$insert into public.run_operation_receipts(user_id,operation_id,kind) values(auth.uid(),'a2160000-0000-4000-8000-000000000099','create')$$,'42501',null,'Authenticated cannot forge receipts');
select throws_ok($$update public.run_operation_receipts set deleted=false$$,'42501',null,'Authenticated cannot reset tombstones');
insert into run_ids select id from public.run_create('a2160000-0000-4000-8000-000000000001','Run',null,(select value from summary));
select is((select count(*) from public.run_create('a2160000-0000-4000-8000-000000000001','Run',null,(select value from summary))),1::bigint,'Lost-response create returns one existing run');
select is((select count(*) from public.workouts where user_id=auth.uid()),1::bigint,'Create replay stores one row');
select is((select started_at=completed_at from public.run_get((select id from run_ids))),true,'Date-only envelope uses equal synthetic anchors');
select is((select details->'runSummary'->>'activityDate' from public.run_get((select id from run_ids))),'2026-10-01','UTC+14 preserves entered date');
select is((select count(*) from public.run_list('2026-10-01','2026-10-01',null,10)),1::bigint,'Date filter precedes limit using activity day');
select throws_ok($$select * from public.run_create('a2160000-0000-4000-8000-000000000001','Changed',null,(select value from summary))$$,'40001','run_conflict','Changed create payload conflicts');
select throws_ok($$insert into public.workout_sets(user_id,workout_id,exercise_id,sequence) values(auth.uid(),(select id from run_ids),'f2160000-0000-4000-8000-000000000099',1)$$,'22023','run_invalid','Direct set cannot attach to run before FK acceptance');
select throws_ok($$update public.workouts set details='{}' where id=(select id from run_ids)$$,'42501','run_requires_rpc','Direct owned update cannot strip run metadata');
select throws_ok($$delete from public.workouts where id=(select id from run_ids)$$,'42501','run_requires_rpc','Direct delete cannot bypass receipt tombstoning');
select throws_ok($$insert into public.workouts(user_id,name,started_at,completed_at,details) values(auth.uid(),'Bypass',now(),now(),'{"activityType":"running"}')$$,'42501','run_requires_rpc','Direct owned insert cannot create reserved run data');
select throws_ok($$select * from public.run_create('a2160000-0000-4000-8000-000000000004','Run',null,(select value || '{"distanceMeters":0}'::jsonb from summary))$$,'22023','run_invalid','Direct RPC rejects zero distance');
select throws_ok($$select * from public.run_create('a2160000-0000-4000-8000-000000000004','Run',null,(select value || '{"durationBasis":null}'::jsonb from summary))$$,'22023','run_invalid','Direct RPC rejects explicit null duration basis');
select throws_ok($$select * from public.run_create('a2160000-0000-4000-8000-000000000004','Run',null,(select value || '{"environment":null}'::jsonb from summary))$$,'22023','run_invalid','Direct RPC rejects explicit null environment');
select throws_ok($$select * from public.run_create('a2160000-0000-4000-8000-000000000004','Run',null,(select value || '{"timestampEnvelope":null}'::jsonb from summary))$$,'22023','run_invalid','Direct RPC rejects explicit null envelope');
select throws_ok($$select * from public.run_create('a2160000-0000-4000-8000-000000000004','Run',null,(select value || '{"distanceMeters":1.001}'::jsonb from summary))$$,'22023','run_invalid','Direct RPC rejects unsupported precision');
reset role;
-- Reach running publication guard rather than stop at the disabled Community pilot switch.
update public.community_operations set enabled=true,publish=true,cohort_required=false;
select throws_ok($$insert into public.shared_activities(user_id,source_workout_id,category,shared_day) values('f2160000-0000-4000-8000-000000000001',(select id from run_ids),'running','2026-10-01')$$,'22023','run_invalid','SQL publication cannot bypass running guard');
select throws_ok($$insert into public.community_routine_shares(user_id,source_workout_id,source_updated_at,operation_id,enrollment_generation,snapshot) values('f2160000-0000-4000-8000-000000000001',(select id from run_ids),now(),'a2160000-0000-4000-8000-000000000088',1,'{}')$$,'22023','run_invalid','SQL routine sharing cannot attach run');
select throws_ok($$insert into public.community_challenge_contributions(user_id,challenge_id,day,kind,source_workout_id,source_updated_at) values('f2160000-0000-4000-8000-000000000001','a2160000-0000-4000-8000-000000000088','2026-10-01','workout',(select id from run_ids),now())$$,'22023','run_invalid','SQL challenge cannot attach run before FK acceptance');
set local role authenticated;
select lives_ok($$select * from public.run_update((select id from run_ids),'a2160000-0000-4000-8000-000000000002',1,'Run',null,(select value || '{"revision":2,"durationSeconds":1900}'::jsonb from summary))$$,'CAS edit succeeds');
select lives_ok($$select * from public.run_update((select id from run_ids),'a2160000-0000-4000-8000-000000000002',1,'Run',null,(select value || '{"revision":2,"durationSeconds":1900}'::jsonb from summary))$$,'Lost edit response replays acknowledged revision');
select throws_ok($$select * from public.run_update((select id from run_ids),'a2160000-0000-4000-8000-000000000005',1,'Run',null,(select value || '{"revision":2,"durationSeconds":1901}'::jsonb from summary))$$,'40001','run_conflict','Two-device stale revision conflicts');
select lives_ok($$select * from public.run_update((select id from run_ids),'a2160000-0000-4000-8000-000000000006',2,'Run',null,(select value || '{"revision":3,"durationSeconds":2000}'::jsonb from summary))$$,'Newer edit succeeds');
select throws_ok($$select * from public.run_update((select id from run_ids),'a2160000-0000-4000-8000-000000000002',1,'Run',null,(select value || '{"revision":2,"durationSeconds":1900}'::jsonb from summary))$$,'40001','run_conflict','Old acknowledged edit cannot replace newer content');
set local request.jwt.claim.sub='f2160000-0000-4000-8000-000000000002';
select is((select count(*) from public.run_get((select id from run_ids))),0::bigint,'Other account cannot read run');
select is((select count(*) from public.run_operation_receipts),0::bigint,'Other account cannot read receipt');
select throws_ok($$select * from public.run_update((select id from run_ids),'a2160000-0000-4000-8000-000000000005',3,'Run',null,(select value || '{"revision":4}'::jsonb from summary))$$,'P0002','run_not_found','Other account cannot edit run');
select lives_ok($$select * from public.run_remove((select id from run_ids))$$,'Other account delete exposes no ownership');
set local request.jwt.claim.sub='f2160000-0000-4000-8000-000000000001';
select is((select count(*) from public.run_get((select id from run_ids))),1::bigint,'Other account delete leaves owner run');
select lives_ok($$select * from public.run_remove((select id from run_ids))$$,'Delete succeeds');
select lives_ok($$select * from public.run_remove((select id from run_ids))$$,'Lost delete response retries');
select throws_ok($$select * from public.run_create('a2160000-0000-4000-8000-000000000001','Run',null,(select value from summary))$$,'P0003','run_removed','Late create cannot resurrect deleted run');
select throws_ok($$select * from public.run_update((select id from run_ids),'a2160000-0000-4000-8000-000000000008',3,'Run',null,(select value || '{"revision":4}'::jsonb from summary))$$,'P0003','run_removed','Late update cannot resurrect deleted run');
select lives_ok($$select * from public.run_cancel('a2160000-0000-4000-8000-000000000003')$$,'Cancellation tombstones an operation before row exists');
select throws_ok($$select * from public.run_create('a2160000-0000-4000-8000-000000000003','Run',null,(select value from summary))$$,'P0003','run_removed','Pending cancellation survives late create');
select is((select count(*) from public.workouts where user_id=auth.uid()),0::bigint,'Deleted runs absent');
reset role;
delete from auth.users where id='f2160000-0000-4000-8000-000000000001';
select is((select count(*) from public.run_operation_receipts where user_id='f2160000-0000-4000-8000-000000000001'),0::bigint,'Account erasure cascades minimal receipts');
select * from finish();
rollback;
